using System.Reflection;
using System.Text.Encodings.Web;

internal static class ConfigurationShell
{
    public static string Render(string title, string content, string active)
    {
        string version = typeof(ConfigurationShell).Assembly.GetName().Version?.ToString() ?? "unknown";
        string html = """
<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>__TITLE__ · Aegis Configuration</title>
<style>__CSS__</style>
</head>
<body>
<header class="lcars-top">
  <div class="left-vertical"></div><div class="left-gold"></div><div class="bottom-arm"></div><div class="join-dot"></div>
  <div class="brand"><div class="aegis">Aegis LCARS</div><div class="section">Configuration</div><div class="org">Food For The Poor Jamaica</div></div>
  <div class="live-log" id="liveLog">
    <div class="row"><span class="t">--:--:--</span> <span class="inf">INF</span> <span class="src">[Configuration]</span> Loading configuration authority</div>
    <div class="row"><span class="t">--:--:--</span> <span class="inf">INF</span> <span class="src">[Contracts]</span> Loading application contracts</div>
    <div class="row"><span class="t">--:--:--</span> <span class="inf">INF</span> <span class="src">[Registration]</span> Loading lifecycle state</div>
  </div>
  <div class="current-system">
    <div class="wave" aria-hidden="true"><svg viewBox="0 0 48 48"><path d="M5 8h16l6 6h16v26H5z"/><path d="M5 18h38"/></svg></div>
    <div class="sys-meta"><strong>Aegis.Configuration</strong><span>v__VERSION__</span><span>Configuration Authority</span><div class="health"><i id="healthDot"></i><span id="healthText">SCANNING</span></div></div>
  </div>
  <div class="top-buttons"><button class="gold" onclick="location.reload()">Refresh</button><a class="blue" href="/contracts">Contracts</a><a class="purple" href="/runbooks">Runbooks</a><a class="gray" href="/registration-lifecycle">Registration</a></div>
  <div class="clock"><div class="date" id="date"></div><div class="time" id="time"></div><small id="zone"></small></div>
</header>

<section class="workspace-shell">
  <div class="workspace-arm"></div><div class="workspace-leg"></div>
  <nav class="workspace-nav"><a class="__APPS__" href="/">Applications</a><a class="__CONTRACTS__" href="/contracts">Contracts</a><a class="__RUNBOOKS__" href="/runbooks">Runbooks</a><a href="/registration-lifecycle">Registration</a></nav>
  <main class="detail-scroll">__CONTENT__</main>
</section>

<div class="footer-wrap">
  <footer class="footer-bar">
    <a class="footer-item" href="https://operations.ffpja.org"><span class="footer-icon"><svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="10"/><path d="M16 6v4M16 22v4M6 16h4M22 16h4"/><circle cx="16" cy="16" r="3"/></svg></span><span><strong>Operations</strong><small>Monitor · Deploy · Manage</small></span></a>
    <a class="footer-item active" href="/"><span class="footer-icon"><svg viewBox="0 0 32 32"><circle cx="16" cy="16" r="5"/><path d="M16 3v5M16 24v5M3 16h5M24 16h5M7 7l4 4M21 21l4 4M25 7l-4 4M11 21l-4 4"/></svg></span><span><strong>Configuration</strong><small>Settings · Secrets · Registration</small></span></a>
    <a class="footer-item" href="https://diagnostics.ffpja.org"><span class="footer-icon"><svg viewBox="0 0 32 32"><path d="M2 17h7l3-9 5 18 4-13 3 7h6"/></svg></span><span><strong>Diagnostics</strong><small>Health · Logs · Analysis</small></span></a>
    <div class="footer-status"><span><i id="footerHealth"></i><b id="configSummary">Configuration status unavailable</b></span></div>
    <div class="footer-env">CONTROL PLANE</div><div class="footer-user"><span><b>Configuration</b><small>Authority</small></span></div><div class="footer-logout"></div>
  </footer>
  <div class="footer-meta">Aegis LCARS v__VERSION__ | Food For The Poor Jamaica</div><div class="footer-motto">Own what makes us different.</div>
</div>

<script>
const localDateTime=v=>{const d=v instanceof Date?v:new Date(v);return Number.isNaN(d.getTime())?String(v??'—'):d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'medium'});};
function clockTick(){const d=new Date();date.textContent=d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase();time.textContent=d.toLocaleTimeString('en-GB',{hour12:false});zone.textContent=Intl.DateTimeFormat().resolvedOptions().timeZone;} clockTick();setInterval(clockTick,1000);
const q=document.getElementById('search'),f=document.getElementById('statusFilter');
const filterRows=()=>document.querySelectorAll('#apps tbody tr').forEach(r=>r.style.display=(!q||r.innerText.toLowerCase().includes(q.value.toLowerCase()))&&(!f||!f.value||r.innerText.toLowerCase().includes(f.value.toLowerCase()))?'':'none');if(q)q.addEventListener('input',filterRows);if(f)f.addEventListener('change',filterRows);
document.querySelectorAll('#apps tbody tr').forEach(r=>{const a=r.querySelector('a[href^="/applications/"]');if(!a)return;r.classList.add('app-row');r.setAttribute('role','link');r.setAttribute('tabindex','0');const go=e=>{if(e&&e.target&&e.target.closest&&e.target.closest('a,button,input,select'))return;location.href=a.href;};r.addEventListener('click',go);r.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();location.href=a.href;}});});
function setLog(level,source,message){const row=document.createElement('div');row.className='row';row.innerHTML='<span class="t">'+new Date().toLocaleTimeString('en-GB',{hour12:false})+'</span> <span class="'+level.toLowerCase()+'">'+level+'</span> <span class="src">['+source+']</span> '+message;liveLog.appendChild(row);while(liveLog.children.length>5)liveLog.removeChild(liveLog.firstElementChild);}
(async()=>{try{const h=await fetch('/health',{cache:'no-store'}).then(r=>r.ok?r.json():null);const summary=await fetch('/api/registration/summary',{cache:'no-store'}).then(r=>r.ok?r.json():null).catch(()=>null);const rows=[...document.querySelectorAll('#apps tbody tr')].filter(r=>r.querySelector('a[href^="/applications/"]'));const configured=rows.filter(r=>r.querySelector('.status.good')).length;const allConfigured=rows.length>0&&configured===rows.length;const healthy=String(h?.health??h?.status??'Healthy').toLowerCase()==='healthy';const attention=(summary?.attention??0)+(rows.length-configured);const ok=healthy&&attention===0;healthText.textContent=ok?'HEALTHY':'ATTENTION';healthDot.style.background=ok?'var(--green)':'var(--yellow)';footerHealth.style.background=ok?'var(--green)':'var(--yellow)';configSummary.textContent=rows.length?(configured+' of '+rows.length+' Configured'+(summary?(' · '+(summary.registered??0)+' Registered'):'')):'No Applications Registered';setLog('INF','Configuration','Health '+(h?.health??h?.status??'Unknown'));setLog(attention?'WRN':'INF','Registration',summary?((summary.registered??0)+' registered · '+(summary.attention??0)+' attention'):'Registration summary unavailable');setLog(allConfigured?'INF':'WRN','Contracts',(configured+' of '+rows.length+' configured'));}catch{healthText.textContent='UNAVAILABLE';healthDot.style.background='var(--red)';footerHealth.style.background='var(--red)';setLog('ERR','Configuration','Status telemetry unavailable');}})();
document.querySelectorAll('time.local-datetime[datetime]').forEach(x=>{x.textContent=localDateTime(x.getAttribute('datetime'));});
</script>
</body>
</html>
""";
        return html
            .Replace("__TITLE__", HtmlEncoder.Default.Encode(title), StringComparison.Ordinal)
            .Replace("__CSS__", BaseCss + "\n" + GlossyCss.Value, StringComparison.Ordinal)
            .Replace("__APPS__", active == "applications" ? "active" : "", StringComparison.Ordinal)
            .Replace("__RUNBOOKS__", active == "runbooks" ? "active" : "", StringComparison.Ordinal)
            .Replace("__CONTRACTS__", active == "contracts" ? "active" : "", StringComparison.Ordinal)
            .Replace("__VERSION__", HtmlEncoder.Default.Encode(version), StringComparison.Ordinal)
            .Replace("__CONTENT__", content, StringComparison.Ordinal);
    }

    private const string BaseCss = """
