.page-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:16px}.page-head h1{font-size:31px;margin:0;color:var(--blue)}.page-head p{margin:4px 0 0;color:#c1d4e4}.toolbar{display:flex;gap:10px;margin:10px 0}.toolbar input{flex:1}.toolbar input,.toolbar select,.toolbar button,.primary,dialog button{background:#071722;color:white;border:1px solid var(--line);border-radius:8px;padding:11px}.primary{background:#087fff!important;font-weight:800}
