.detail{padding:16px}.detail-head{display:flex;gap:12px;align-items:center;border-bottom:1px solid var(--line-soft);padding-bottom:13px}.bigicon{width:58px;height:58px;border-radius:9px;background:#087fff;display:grid;place-items:center;font-size:30px}.detail-head h2{margin:0;font-size:24px}.detail-head .status{margin-left:auto}.facts{display:grid;grid-template-columns:repeat(2,1fr);margin:10px 0}.facts div{padding:8px;border-right:1px solid var(--line-soft)}.facts small,.facts b{display:block}.facts small{color:#7fa7c2;font-size:10px}.tabs{display:flex;gap:18px;border-bottom:1px solid var(--line-soft);padding:10px 0}.tabs b{color:#62c6ff;border-bottom:2px solid #2aa8ff;padding-bottom:8px}.detail h3,.panel h3{font-size:14px}.req{display:grid;grid-template-columns:1fr auto 28px;gap:8px;padding:9px;border-bottom:1px solid var(--line-soft)}.req small{display:block;color:#8daabd}.req code{color:#80d5ff}.req i{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-style:normal}.req i.ok{background:#08764e}.req i.bad{background:#986016}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:14px}.actions a{border:1px solid var(--line);padding:9px;text-align:center;border-radius:8px}.lower{display:grid;grid-template-columns:1.2fr .8fr;gap:14px;margin-top:14px}.lower .panel{padding:12px}.activity-row{display:grid;grid-template-columns:16px 1fr auto;gap:8px;padding:7px;border-bottom:1px solid var(--line-soft)}.activity-row i{width:10px;height:10px;border-radius:50%;background:var(--green)}.activity-row small{display:block;color:#8caabd}.activity-row time{color:#7bbfe8;font-size:11px}.quick{display:grid;grid-template-columns:1fr 1fr;gap:8px}.quick a{border:1px solid var(--line);border-radius:8px;padding:9px;display:flex;gap:8px}.quick small{display:block;color:#91adc1}.empty{padding:20px;color:#8faabd;text-align:center}.muted{color:#8faabd}dialog{background:#06111b;color:white;border:1px solid var(--line);border-radius:10px;max-width:520px;padding:22px}dialog::backdrop{background:#000a}
.footer-wrap{position:fixed;left:8px;right:14px;bottom:8px;height:92px;z-index:30}.footer-bar{position:absolute;left:0;right:0;top:0;height:70px;border:0;border-radius:22px 0 0 22px;background:#02060a;display:grid;grid-template-columns:225px 285px 235px 1fr 150px 170px 58px;align-items:center;overflow:hidden;padding:8px 48px 8px 8px;box-shadow:inset 0 0 0 8px #5da0f5}.footer-bar::after{content:"";position:absolute;right:0;top:0;bottom:0;width:40px;background:var(--gold)}.footer-item{height:100%;display:flex;align-items:center;gap:12px;padding:0 18px;border-right:1px solid var(--line);min-width:0}.footer-item.active{box-shadow:inset 0 0 0 2px #19a7ff;border-radius:14px}.footer-item strong{display:block;color:var(--blue);font-size:16px;text-transform:uppercase}.footer-item small{display:block;color:var(--cyan);font-size:10px;text-transform:uppercase}.footer-icon{width:30px;height:30px;color:var(--blue);display:flex;align-items:center;justify-content:center;flex:0 0 30px}.footer-icon svg{width:26px;height:26px;display:block;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.footer-status{display:flex;align-items:center;justify-content:center;gap:18px;height:100%;border-right:1px solid var(--line);color:var(--cyan);font-size:12px}.footer-status i{width:16px;height:16px;border-radius:50%;background:var(--green)}.footer-env,.footer-user,.footer-logout{height:100%;display:flex;align-items:center;justify-content:center;border-right:1px solid var(--line)}.footer-env{color:var(--blue);font-weight:900}.footer-user small{display:block;color:#b9c4d0}.footer-meta{position:absolute;left:50px;bottom:0;color:#aebdca;font-size:11px}.footer-motto{position:absolute;right:72px;bottom:0;color:#cdd7e1;font-size:12px}
